func (q *Queries) RollbackTarget(ctx context.Context, arg RollbackTargetParams) (ReleaseRelease, error) {
	row := q.db.QueryRow(ctx, rollbackTarget, arg.ProjectID, arg.Environment, arg.CurrentVersion)
	var i ReleaseRelease
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ProjectID,
		&i.Version,
		&i.ParentID,
		&i.Environment,
		&i.Policy,
		&i.Content,
		&i.ManifestDigest,
		&i.Stats,
		&i.Note,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.Branch,
	)
	return i, err
}

const servedInEnvironment = `-- name: ServedInEnvironment :one
SELECT EXISTS (
    SELECT 1 FROM release_deployments
    WHERE project_id = $1 AND environment = $2 AND release_id = $3
)
`

type ServedInEnvironmentParams struct {
	ProjectID   uuid.UUID
	Environment string
	ReleaseID   uuid.UUID
}

func (q *Queries) ServedInEnvironment(ctx context.Context, arg ServedInEnvironmentParams) (bool, error) {
	row := q.db.QueryRow(ctx, servedInEnvironment, arg.ProjectID, arg.Environment, arg.ReleaseID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const setDeliveryKeyScope = `-- name: SetDeliveryKeyScope :execrows
UPDATE release_delivery_keys
SET environments = $1::text[], branches = $2, index_version = 1
WHERE project_id = $3 AND id = $4 AND revoked_at IS NULL
`

type SetDeliveryKeyScopeParams struct {
	Environments []string
	Branches     bool
	ProjectID    uuid.UUID
	ID           uuid.UUID
}

// Replaces what an active key reads (RFC 0004 §4.3). index_version
// drops to 1 (before scopes), so the key index task rewrites the object
// if the write that follows the change doesn't reach storage.
func (q *Queries) SetDeliveryKeyScope(ctx context.Context, arg SetDeliveryKeyScopeParams) (int64, error) {
	result, err := q.db.Exec(ctx, setDeliveryKeyScope,
		arg.Environments,
		arg.Branches,
		arg.ProjectID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateEnvironment = `-- name: UpdateEnvironment :execrows
UPDATE release_environments
SET policy = $1, approval = $2, current_release_id = $3,
    version = $4, updated_at = $5
WHERE project_id = $6 AND name = $7 AND version = $8
`

type UpdateEnvironmentParams struct {
	Policy           json.RawMessage
	Approval         []byte
	CurrentReleaseID uuid.NullUUID
	Version          int32
	UpdatedAt        time.Time
	ProjectID        uuid.UUID
	Name             string
	ExpectedVersion  int32
}

func (q *Queries) UpdateEnvironment(ctx context.Context, arg UpdateEnvironmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateEnvironment,
		arg.Policy,
		arg.Approval,
		arg.CurrentReleaseID,
		arg.Version,
		arg.UpdatedAt,
		arg.ProjectID,
		arg.Name,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
